@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600;700&display=swap');
:root{--ink:#111218;--panel:#191a22;--panel2:#20212b;--line:#34343e;--gold:#e5b968;--gold2:#f2d89f;--cream:#f1eee8;--muted:#9897a3;--red:#c96c69;--teal:#7aa99f;--serif:'Playfair Display',Georgia,serif;--sans:'DM Sans',Arial,sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--ink);color:var(--cream);font-family:var(--sans);min-height:100vh;background-image:radial-gradient(ellipse at 50% -10%,#292630 0,transparent 52%),radial-gradient(ellipse at 0 70%,#1c1c26 0,transparent 40%)}button{font:inherit;color:inherit}.app-shell{max-width:1480px;margin:auto;padding:0 40px}.topbar{height:82px;border-bottom:1px solid #ffffff13;display:flex;align-items:center;justify-content:space-between}.wordmark{display:flex;align-items:center;gap:12px;color:var(--cream);text-decoration:none;font-size:12px;font-weight:700;letter-spacing:2px}.wordmark i{font-style:normal;color:var(--gold);font-family:var(--serif);font-size:17px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid #c9a66577;border-radius:50%;font-size:17px;color:var(--gold)}.topbar-center{font-size:9px;letter-spacing:2.6px;color:#a6a4ad;display:flex;align-items:center;gap:9px}.live-dot{height:6px;width:6px;background:var(--gold);border-radius:50%;box-shadow:0 0 8px #e5b968}.topbar-actions{display:flex;align-items:center;gap:20px}.icon-button,.text-button{background:none;border:0;cursor:pointer}.icon-button{font-size:18px;color:var(--gold);padding:8px}.text-button{font-size:9px;letter-spacing:1.6px;color:#d0ccd0}.text-button span{color:var(--gold);margin-left:5px}.site-footer{height:52px;display:flex;align-items:center;justify-content:space-between;color:#74737d;font-size:8px;letter-spacing:1.5px;border-top:1px solid #ffffff10}.site-footer span:nth-child(2){color:#9e8a68}.screen{min-height:calc(100vh - 135px)}.eyebrow{font-size:9px;font-weight:700;letter-spacing:2.4px;color:var(--gold);text-transform:uppercase}.serif{font-family:var(--serif)}
/* title screen */
.title-screen{padding:42px 0 46px;max-width:1190px;margin:auto}.title-heading{text-align:center;margin:15px auto 34px}.title-heading .eyebrow{margin-bottom:13px}.title-heading h1{font-family:var(--serif);font-size:clamp(39px,5vw,63px);font-weight:500;line-height:1.05;letter-spacing:-1.6px;margin:0}.title-heading h1 em{color:var(--gold);font-weight:500}.title-heading p{color:#aaa7b0;font-size:13px;margin:14px auto 0;max-width:530px;line-height:1.7}.creation-layout{display:grid;grid-template-columns:1.1fr .9fr;gap:22px;align-items:stretch}.section-card{background:linear-gradient(145deg,#1d1e27ed,#17181ff2);border:1px solid #ffffff14;border-radius:8px;padding:22px 24px;position:relative;overflow:hidden}.section-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.section-title h2{font:600 16px var(--serif);margin:0}.section-title span{font-size:8px;letter-spacing:1.4px;color:#85838e}.campaign-list{display:grid;gap:10px}.campaign-card{border:1px solid #ffffff16;background:#ffffff03;border-radius:5px;display:grid;grid-template-columns:104px 1fr 22px;gap:14px;min-height:104px;padding:9px;text-align:left;cursor:pointer;transition:.2s;position:relative}.campaign-card:hover,.campaign-card.selected{border-color:#d6ad607c;background:#c99e2a0a;transform:translateY(-1px)}.campaign-card.selected:after{content:'✓';position:absolute;right:13px;top:11px;color:var(--gold);font-size:13px}.campaign-art{border-radius:3px;position:relative;overflow:hidden;display:grid;place-items:center;font-size:36px;color:#eed1a1;background:radial-gradient(circle at 54% 37%,#be78519a 0,#754539 24%,#30232a 62%,#16161e 100%)}.campaign-card:nth-child(2) .campaign-art{background:radial-gradient(circle at 60% 32%,#8ca4a5 0,#415b60 32%,#25313a 65%,#17181f 100%)}.campaign-card:nth-child(3) .campaign-art{background:radial-gradient(circle at 54% 35%,#ab8c58 0,#675341 30%,#3b3040 68%,#1a1922 100%)}.campaign-art:after{content:'';position:absolute;inset:auto 0 0;height:40%;background:linear-gradient(transparent,#13141b)}.campaign-meta{align-self:center;padding:1px 5px 1px 0}.campaign-meta .tag{font-size:8px;letter-spacing:1.5px;color:var(--gold);font-weight:700}.campaign-meta h3{font:600 17px var(--serif);margin:5px 0 5px}.campaign-meta p{font-size:10px;line-height:1.5;color:#a6a4ad;margin:0;max-width:340px}.campaign-meta .campaign-foot{display:flex;gap:9px;margin-top:8px;color:#807e89;font-size:8px;letter-spacing:.5px}.arrow{align-self:center;color:#8f8b92;font-size:18px}.hero-options{display:grid;gap:9px}.hero-card{display:flex;align-items:center;gap:12px;padding:11px;border:1px solid #ffffff15;background:#ffffff03;border-radius:5px;text-align:left;cursor:pointer;transition:.2s}.hero-card:hover,.hero-card.selected{border-color:#d6ad607c;background:#c99e2a0a}.hero-sigil{width:44px;height:44px;border-radius:50%;display:grid;place-items:center;flex:none;font-size:20px;border:1px solid #c89f5555;background:radial-gradient(circle,#a6784380,#37303a 70%)}.hero-info{flex:1}.hero-info strong{display:block;font:600 15px var(--serif);margin-bottom:3px}.hero-info small{color:#aaa7af;font-size:9px}.hero-info .specialty{color:var(--gold);font-size:8px;letter-spacing:1px;margin-top:6px;text-transform:uppercase}.hero-card .check{color:var(--gold);font-size:13px;opacity:0}.hero-card.selected .check{opacity:1}.creation-note{display:flex;align-items:center;gap:10px;margin-top:13px;color:#92909a;font-size:9px;line-height:1.5}.creation-note b{color:var(--gold);font-weight:500}.start-row{display:flex;justify-content:center;margin:24px auto 0}.primary-button{background:linear-gradient(120deg,#ddba72,#c99c4b);color:#17161a;border:0;padding:14px 30px;border-radius:3px;letter-spacing:1.3px;font-size:10px;font-weight:700;cursor:pointer;box-shadow:0 5px 20px #c69e3b18;transition:.2s}.primary-button:hover{background:#f2d89f;transform:translateY(-2px);box-shadow:0 8px 25px #c69e3b30}.primary-button span{margin-left:13px;font-size:15px}.resume-link{display:block;margin:11px auto 0;background:none;border:0;color:#a6a3ac;font-size:9px;letter-spacing:1px;text-decoration:underline;text-underline-offset:3px;cursor:pointer}
/* game */
.game-screen{padding:28px 0 34px}.game-topline{display:flex;align-items:center;justify-content:space-between;padding:0 3px 17px;margin-bottom:18px;border-bottom:1px solid #ffffff12}.chapter-info{display:flex;align-items:center;gap:10px}.chapter-info .chapter-kicker{font-size:8px;letter-spacing:1.7px;color:var(--gold)}.chapter-info strong{font:500 14px var(--serif)}.chapter-progress{display:flex;align-items:center;gap:5px}.chapter-progress i{height:3px;width:24px;background:#ffffff1a;border-radius:3px}.chapter-progress i.done{background:var(--gold)}.game-actions{display:flex;gap:8px}.small-action{background:none;border:1px solid #ffffff1a;border-radius:3px;padding:7px 10px;color:#aaa7b0;font-size:8px;letter-spacing:1px;cursor:pointer}.small-action:hover{border-color:#b99c6b;color:var(--gold)}.game-grid{display:grid;grid-template-columns:207px minmax(0,1fr) 222px;gap:18px;align-items:start}.side-card{background:#1b1c24c9;border:1px solid #ffffff12;border-radius:5px;padding:16px}.side-heading{font-size:8px;letter-spacing:1.7px;color:#aaa7b0;margin:0 0 13px}.character-banner{height:122px;margin:-16px -16px 13px;border-radius:5px 5px 0 0;display:grid;place-items:center;position:relative;overflow:hidden;background:radial-gradient(circle at 50% 43%,#aa775b 0,#59414a 25%,#292631 64%,#1b1c24 100%)}.character-banner:before{content:'';position:absolute;bottom:-38px;left:50%;transform:translateX(-50%);width:96px;height:105px;border-radius:48% 48% 0 0;background:linear-gradient(140deg,#c7a982,#574b55 58%,#24232d);filter:drop-shadow(0 0 15px #e3b16930)}.character-banner:after{content:'';position:absolute;top:15px;width:41px;height:49px;border-radius:48% 48% 43% 43%;background:linear-gradient(145deg,#e1bc8a,#88664f 75%);box-shadow:0 -8px 0 -3px #312936}.character-banner .banner-symbol{position:absolute;z-index:2;top:20px;right:18px;color:#f4d296;font-size:17px;text-shadow:0 0 15px #f4d296}.character-name{text-align:center;font:600 18px var(--serif);margin:0}.character-class{text-align:center;color:var(--gold);font-size:8px;letter-spacing:1.3px;text-transform:uppercase;margin-top:4px}.stat-block{margin-top:16px}.stat-row{display:flex;align-items:center;justify-content:space-between;font-size:9px;color:#aaa7b0;margin:10px 0 5px}.stat-row strong{color:#e4e0da;font-size:9px}.meter{height:5px;border-radius:6px;background:#ffffff15;overflow:hidden}.meter span{display:block;height:100%;border-radius:6px;transition:width .35s}.meter.hp span{background:linear-gradient(90deg,#a84d4d,#df8271)}.meter.gold span{background:linear-gradient(90deg,#a67d35,#e8c67f)}.meter.will span{background:linear-gradient(90deg,#526b93,#89a8d7)}.level-row{display:flex;align-items:center;justify-content:space-between;margin-top:16px;padding-top:12px;border-top:1px solid #ffffff12;font-size:9px;color:#aaa7b0}.level-badge{color:var(--gold);font-weight:700;letter-spacing:1px}.party-list{margin-top:15px;padding-top:13px;border-top:1px solid #ffffff12}.party-person{display:flex;align-items:center;gap:8px;margin:9px 0}.party-avatar{width:25px;height:25px;display:grid;place-items:center;background:#33303a;border-radius:50%;font-size:12px}.party-person span:last-child{font-size:9px;color:#d1cdd0}.story-column{min-width:0}.scene-art{height:204px;border-radius:5px;position:relative;overflow:hidden;display:flex;align-items:flex-end;padding:16px 20px;background:#282530;margin-bottom:16px;border:1px solid #ffffff13}.scene-art:before,.scene-art:after{content:'';position:absolute;inset:0;pointer-events:none}.scene-art:before{background:linear-gradient(0deg,#101117 0%,transparent 66%),linear-gradient(90deg,#1011176b,transparent 75%)}.scene-art:after{opacity:.55;background:radial-gradient(ellipse at 78% 15%,#f1cb8566 0,transparent 25%)}.scene-art .scene-landscape{position:absolute;inset:0;overflow:hidden}.landscape-sun{position:absolute;right:20%;top:12%;width:67px;height:67px;border-radius:50%;background:#dfaa63;box-shadow:0 0 40px #d38b57aa,0 0 90px #cf804777}.landscape-mountain{position:absolute;bottom:-10%;left:-5%;width:75%;height:83%;background:linear-gradient(150deg,#706270,#2c2937 65%);clip-path:polygon(0 100%,36% 25%,48% 47%,67% 0,100% 100%)}.landscape-mountain.back{left:33%;width:76%;height:74%;background:linear-gradient(130deg,#62515a,#282631 70%);clip-path:polygon(0 100%,27% 28%,40% 49%,66% 4%,100% 100%)}.landscape-spire{position:absolute;bottom:15%;right:19%;height:62%;width:39px;background:linear-gradient(90deg,#211f2a,#71615c,#282530);clip-path:polygon(50% 0,65% 28%,100% 100%,0 100%,35% 27%)}.landscape-spire:after{content:'';position:absolute;top:42%;left:44%;width:5px;height:23px;background:#e4b668;box-shadow:0 0 15px 3px #e3a65c}.scene-art.cold .landscape-sun{background:#9fc6d1;box-shadow:0 0 36px #a5dce099,0 0 100px #71b3c366}.scene-art.cold .landscape-mountain{background:linear-gradient(150deg,#718c9a,#27313f 68%)}.scene-art.green .landscape-sun{background:#d6c07d;box-shadow:0 0 40px #c9c07888,0 0 90px #74b79c44}.scene-art.green .landscape-mountain{background:linear-gradient(150deg,#708269,#263d3d 68%)}.scene-art .art-caption{position:relative;z-index:1;font-size:8px;letter-spacing:2px;color:#e3c991;text-transform:uppercase}.scene-art .scene-emblem{position:absolute;top:15px;left:18px;z-index:1;font-size:9px;letter-spacing:1.8px;color:#ffffffbb}.narrative-panel{background:linear-gradient(145deg,#1c1d25,#17181f);border:1px solid #ffffff12;border-radius:5px;padding:21px 24px 19px;position:relative}.narrative-panel:before{content:'';position:absolute;top:-1px;left:24px;width:45px;height:2px;background:var(--gold)}.narrative-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.narrative-heading .eyebrow{font-size:8px}.narrative-heading h1{font:600 25px/1.2 var(--serif);margin:7px 0 0}.scene-count{font-size:8px;color:#8f8c97;letter-spacing:1px;white-space:nowrap;margin-top:4px}.narrative-text{font:500 14px/1.82 'Cormorant Garamond',Georgia,serif;color:#d2cdd0;margin:14px 0 16px;white-space:pre-line}.narrative-text strong{color:var(--gold2);font-weight:600}.companion-line{padding:10px 12px;border-left:2px solid #9a7a4c;background:#ffffff05;color:#aaa5ae;font:italic 12px/1.5 var(--serif);margin:0 0 17px}.companion-line b{color:#dfc184;font-weight:600;font-style:normal}.choices{display:grid;gap:7px}.choice-button{width:100%;display:flex;align-items:center;gap:11px;text-align:left;padding:11px 12px;border:1px solid #ffffff14;background:#ffffff04;border-radius:3px;cursor:pointer;transition:.18s}.choice-button:hover:not(:disabled){border-color:#c49e5e99;background:#c49e5e0b;transform:translateX(2px)}.choice-button:disabled{opacity:.42;cursor:not-allowed}.choice-num{width:22px;height:22px;display:grid;place-items:center;border:1px solid #ffffff26;border-radius:50%;color:var(--gold);font:11px var(--serif);flex:none}.choice-copy{flex:1}.choice-copy strong{font:600 12px var(--sans);color:#e6e1dc}.choice-copy small{display:block;color:#a19da7;font-size:9px;margin-top:4px;line-height:1.4}.choice-arrow{color:#827d84}.requirements{color:#d58d77!important}.feedback-box{padding:12px 14px;background:#b6995c0d;border:1px solid #c7a35a42;border-radius:3px;font:italic 13px/1.6 var(--serif);color:#d9cebb;margin-top:14px}.feedback-box strong{color:var(--gold)}.ending-actions{display:flex;gap:9px;margin-top:15px}.ending-actions button{flex:1}.journal-card{margin-top:12px}.journal-entry{border-left:1px solid #a48a5b;padding:0 0 10px 11px;margin-left:4px;color:#97949d;font:italic 11px/1.55 var(--serif)}.journal-entry:last-child{padding-bottom:0}.journal-entry b{font-style:normal;color:#d1c9bd;font-weight:500}.inventory-list{display:grid;gap:8px}.item-row{display:grid;grid-template-columns:30px 1fr auto;align-items:center;gap:8px;padding:8px 0;border-bottom:1px solid #ffffff0d}.item-icon{width:29px;height:29px;border:1px solid #c2a15b3b;background:#c4a15b0c;border-radius:3px;display:grid;place-items:center;color:#e3c27b;font-size:14px}.item-row strong{display:block;font:600 11px var(--serif);color:#e0d9ce}.item-row small{display:block;font-size:8px;color:#96929b;margin-top:3px}.item-row .equip{border:0;background:none;color:var(--gold);font-size:8px;letter-spacing:.7px;cursor:pointer;padding:4px}.empty-inventory{font-size:9px;color:#8f8c97;line-height:1.5}.upgrades-list{display:grid;gap:8px}.upgrade-row{display:flex;align-items:center;gap:8px}.upgrade-row .upgrade-icon{width:26px;height:26px;border-radius:50%;background:#24232c;display:grid;place-items:center;color:var(--gold);font-size:12px}.upgrade-row span:nth-child(2){font-size:9px;color:#d4cfd0;flex:1}.upgrade-row small{color:#8f8b95;font-size:8px}.buy-button{background:none;border:1px solid #c3a45b54;border-radius:2px;color:var(--gold);font-size:8px;padding:5px 7px;cursor:pointer}.buy-button:disabled{opacity:.35;cursor:not-allowed}.right-column{display:grid;gap:12px}.aside-card{background:#1b1c24c9;border:1px solid #ffffff12;border-radius:5px;padding:15px}.aside-card .side-heading{display:flex;justify-content:space-between;margin-bottom:12px}.aside-card .side-heading span{color:#77747f;font-size:8px;letter-spacing:1px}.scene-note{font:italic 12px/1.6 var(--serif);color:#aaa5ae}.scene-note b{color:#d8bc81;font-weight:500}.small-divider{height:1px;background:#ffffff10;margin:12px 0}
/* overlays, utility */
.modal-backdrop{position:fixed;inset:0;z-index:10;background:#08090de0;display:grid;place-items:center;padding:20px;backdrop-filter:blur(5px)}.modal{width:min(500px,100%);background:#1d1e27;border:1px solid #a8834d66;border-radius:6px;padding:26px 28px;box-shadow:0 20px 90px #0009}.modal h2{font:600 27px var(--serif);margin:8px 0 12px}.modal p,.modal li{font-size:12px;line-height:1.7;color:#b5b1b8}.modal ul{padding-left:18px}.modal .close-button{float:right;background:none;border:0;color:#aaa;cursor:pointer;font-size:18px}.modal-actions{margin-top:18px;display:flex;gap:9px}.secondary-button{background:none;border:1px solid #ffffff26;padding:12px 16px;border-radius:3px;color:#cbc6c8;font-size:9px;letter-spacing:1px;cursor:pointer}.toast{position:fixed;bottom:23px;left:50%;transform:translate(-50%,20px);padding:10px 16px;border:1px solid #c5a35b66;background:#1f2028;color:#e4d7b6;border-radius:3px;font:11px var(--sans);opacity:0;transition:.25s;pointer-events:none;z-index:30}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:1050px){.app-shell{padding:0 24px}.game-grid{grid-template-columns:185px minmax(0,1fr)}.right-column{grid-column:1/-1;grid-template-columns:1fr 1fr}.story-column{grid-column:2;grid-row:1/3}.left-column{grid-row:1/3}.creation-layout{gap:14px}.section-card{padding:18px}.campaign-card{grid-template-columns:85px 1fr 15px}}
@media(max-width:740px){.app-shell{padding:0 16px}.topbar{height:66px}.topbar-center{display:none}.text-button{font-size:8px}.topbar-actions{gap:8px}.site-footer{font-size:7px}.site-footer span:nth-child(2){display:none}.title-screen{padding-top:27px}.title-heading{margin:8px auto 24px}.title-heading h1{font-size:42px}.title-heading p{font-size:12px}.creation-layout{grid-template-columns:1fr}.section-card{padding:16px}.campaign-card{min-height:94px}.game-screen{padding-top:18px}.game-grid{grid-template-columns:1fr;gap:12px}.left-column,.story-column,.right-column{grid-column:1;grid-row:auto}.left-column{display:grid;grid-template-columns:1fr 1fr;gap:12px}.character-card{grid-column:1/-1}.character-banner{height:94px}.character-card .stat-block{display:grid;grid-template-columns:1fr 1fr;gap:0 13px}.character-card .level-row{grid-column:1/-1}.party-list{display:none}.right-column{grid-template-columns:1fr 1fr}.scene-art{height:175px}.narrative-panel{padding:18px}.narrative-heading h1{font-size:23px}.narrative-text{font-size:14px}.game-topline{align-items:flex-start}.chapter-progress{display:none}.game-actions .small-action{padding:7px;font-size:7px}.story-column{order:0}.left-column{order:1}.right-column{order:2}}
@media(max-width:460px){.app-shell{padding:0 12px}.wordmark{font-size:10px;gap:7px;letter-spacing:1.2px}.brand-mark{height:29px;width:29px}.topbar-actions{gap:2px}.text-button{letter-spacing:.7px}.campaign-card{grid-template-columns:72px 1fr 12px;gap:10px}.campaign-meta h3{font-size:15px}.campaign-meta p{font-size:9px}.campaign-meta .campaign-foot{font-size:7px}.left-column{grid-template-columns:1fr}.character-card{grid-column:auto}.character-banner{height:105px}.right-column{grid-template-columns:1fr}.narrative-heading h1{font-size:21px}.choice-copy strong{font-size:11px}.choice-copy small{font-size:8px}.site-footer{height:40px}}

const heroes = {
  sentinel:{name:'Aldric Vale',role:'Oathbound Sentinel',sigil:'⚔',specialty:'Steel & steadfast resolve',stats:{hp:9,will:5,gold:12},perk:'A steady hand: begin with extra vitality.'},
  arcanist:{name:'Mira Solenne',role:'Veil Arcanist',sigil:'✧',specialty:'Arcana & keen insight',stats:{hp:7,will:9,gold:12},perk:'The unseen thread: begin with extra will.'},
  wanderer:{name:'Tamsin Reed',role:'Wilds Wanderer',sigil:'➶',specialty:'Guile & living wilds',stats:{hp:8,will:7,gold:17},perk:'Fortune favors you: begin with extra coin.'}
};
const campaigns = {
  ash:{title:'The Ashen Crown',kind:'A KINGDOM IN CINDERS',tag:'THE FALLEN REALM',icon:'♜',art:'ember',length:'4 chapters',summary:'A dead king’s crown stirs beneath the mountain. Three claimants march to claim it—and a fourth voice calls from the dark.',companion:'Sister Elowen',companionIcon:'☼',companionLine:'“The crown remembers every hand that has worn it. Let us make this one worth remembering.”',nodes:[
    {chapter:'I · THE LAST LIGHT',location:'The Cinder March',title:'A Crown in the Smoke',text:'Rain hisses on the black road. Behind you, the old capital burns; ahead, a crown-shaped beacon pulses beneath Mount Vey. At your side, <strong>Sister Elowen</strong> clutches a broken royal seal.\n\n“Someone woke the mountain,” she says. “The crown must not choose another tyrant.”',choices:[
      {label:'Offer Elowen the royal seal. Trust her to lead.',hint:'Strengthen your bond · gain an ally’s blessing',effect:{will:1,bond:2,flag:'trustedElowen',journal:'You placed the broken seal in Elowen’s keeping.'},next:1,feedback:'Elowen closes her fingers around the seal. “Then I will carry the hope you have given me.”'},
      {label:'Study the beacon for the spell beneath it.',hint:'Test your will · earn experience and a relic',check:'will',effect:{xp:20,item:'Cinderglass Shard',will:-1,flag:'readTheBeacon',journal:'You learned the beacon answers to an older magic.'},next:1,feedback:'A hidden rune answers your gaze. A shard of cinderglass breaks free, warm as a heartbeat.'},
      {label:'Take the old king’s road. Keep moving.',hint:'A practical route · find a little gold',effect:{gold:8,flag:'kingsRoad',journal:'You followed the old king’s road through the rain.'},next:1,feedback:'You leave the burning skyline behind and find a pouch of forgotten toll coins.'}
    ]},
    {chapter:'I · THE LAST LIGHT',location:'The Pilgrim’s Crossing',title:'Three Banners at the Bridge',text:'At dawn, three armies face one another across a narrow bridge: the iron duke’s soldiers, the people’s militia, and the pale-robed Keepers. Their captains all turn to you.\n\nElowen recognizes the royal seal in her hand. “One word from us could start a war—or end one.”',line:'<b>Elowen:</b> “Ask them what they fear losing. That is where peace begins.”',choices:[
      {label:'Call a parley beneath a banner of truce.',hint:'Appeal to courage and compassion',effect:{will:1,bond:1,flag:'brokeredPeace',journal:'You brought the three banners to the same table.'},next:2,feedback:'The captains lower their weapons long enough to listen. The bridge is yours—for now.'},
      {label:'Challenge the duke’s champion to single combat.',hint:'A test of strength · risk a wound, win renown',effect:{hp:-1,xp:30,flag:'beatChampion',journal:'You defeated the duke’s champion before both armies.'},next:2,feedback:'Your victory rings across the river. Even the duke’s ranks make room for you.'},
      {label:'Slip through the tollhouse and open the old gate.',hint:'Spend 5 gold · avoid the armies',requiresGold:5,effect:{gold:-5,item:'Pilgrim’s Key',flag:'openedGate',journal:'You opened the pilgrim gate without bloodshed.'},next:2,feedback:'The ancient lock yields. You find a pilgrim’s key still hanging within.'}
    ]},
    {chapter:'II · THE HOLLOW MOUNTAIN',location:'The Rootbound Archive',title:'What the Crown Remembers',text:'Beneath the mountain, a library grows from the roots of a petrified tree. Its books are memories, its ink is blood. The crown’s voice fills the vault: it can restore the kingdom, but only by binding every living will to its own.\n\nA second voice stirs inside the cinderglass: the first queen, who made the crown to end a war.',line:'<b>Elowen:</b> “The truth will hurt. But we cannot choose what we refuse to know.”',choices:[
      {label:'Read the queen’s memory, even if it costs you.',hint:'Lose vitality · uncover the crown’s true weakness',effect:{hp:-1,xp:40,flag:'knowsTruth',journal:'You learned the crown was made to contain a buried god.'},next:3,feedback:'The queen’s last memory burns through you. The crown is no kingmaker—it is a prison lock.'},
      {label:'Ask the Keepers to unmake the crown.',hint:'You need the Keepers’ trust',requiresFlag:'brokeredPeace',effect:{will:2,flag:'keepersPlan',journal:'The Keepers agreed to help unmake the crown.'},next:3,feedback:'The Keepers kneel. Their forbidden rite may break the crown without freeing what lies below.'},
      {label:'Take the crown’s bargain: power for one season.',hint:'Gain gold now; the mountain will remember',effect:{gold:20,will:-2,flag:'crownBargain',journal:'You accepted the crown’s bargain for a season of power.'},next:3,feedback:'Gold spills from empty air into your hands. Far below, something stirs.'}
    ]},
    {chapter:'III · THE CROWNING',location:'The Heart Below',title:'The Last Choice',text:'The crown hangs over a dark, starless chasm. The first queen’s spirit reaches for it; the buried god reaches back. Elowen stands beside you, the royal seal shining in her palm.\n\nWhatever you choose, the old kingdom ends tonight.',line:'<b>Elowen:</b> “Whatever comes after, let it be ours to choose.”',choices:[
      {label:'Break the crown and free the kingdom from its old oaths.',hint:'Choose a future with no throne',effect:{flag:'brokeCrown',xp:60,journal:'You shattered the crown and refused the old order.'},ending:'free'},
      {label:'Give the crown to Elowen. Let her rule beside the people.',hint:'Choose a new ruler—and a chance to do better',effect:{flag:'choseElowen',xp:60,journal:'You entrusted the crown to Elowen.'},ending:'queen'},
      {label:'Wear it yourself. Keep the buried god in chains.',hint:'Claim the burden of the crown',effect:{flag:'woreCrown',xp:60,journal:'You took the crown and its burden upon yourself.'},ending:'ruler'}
    ]}
  ],endings:{free:{title:'A Kingdom Without a Crown',text:'The crown breaks like winter ice. Dawn spills through the mountain, and the people walk out beneath an open sky. Elowen keeps the seal—not as a symbol of rule, but as a reminder that no one should own a kingdom.'},queen:{title:'The People’s Queen',text:'Elowen takes the crown only after the people vote to stand with her. Its old magic fades in her hands. Together, you begin a kingdom built by those who once lived beneath its shadow.'},ruler:{title:'The Crown-Bearer',text:'The crown settles on your brow. The buried god falls silent, and the realm kneels. Elowen stays at your side—not as a subject, but as the last voice you promised to hear.'}}},
  frost:{title:'The Winter Star',kind:'A LIGHT LOST TO THE NORTH',tag:'THE FROZEN FRONTIER',icon:'✧',art:'cold',length:'4 chapters',summary:'A fallen star has frozen the northern sea. Venture into the white wilderness before the endless winter takes every shore.',companion:'Kael of the Tide',companionIcon:'❄',companionLine:'“My people have followed these stars for generations. This one… this one is afraid.”',nodes:[
    {chapter:'I · THE WHITE SHORE',location:'The Icebound Coast',title:'A Star Beneath the Ice',text:'The sea has frozen solid in a single night. Far out on the white horizon, a blue star pulses under the ice. Kael, last navigator of the Tidefolk, kneels to press his ear against it.\n\n“It is singing my mother’s song,” he whispers. “She died before the first frost.”',choices:[
      {label:'Kneel beside Kael and listen.',hint:'Build trust · hear the star’s hidden song',effect:{bond:2,will:1,flag:'heardSong',journal:'You listened with Kael to the star beneath the ice.'},next:1,feedback:'A melody moves through the ice and into your bones. Kael looks at you as if you have come home.'},
      {label:'Mark a safe path across the ice.',hint:'Use your wilderness sense · gain experience',effect:{xp:20,gold:5,flag:'markedRoute',journal:'You charted a safe route over the living ice.'},next:1,feedback:'You find a path between the cracks. A trader’s pack lies half-buried nearby.'},
      {label:'Break the ice and reach the star quickly.',hint:'A bold move · risk a wound',effect:{hp:-1,xp:25,flag:'crackedIce',journal:'You broke through the ice to reach the fallen star.'},next:1,feedback:'The ice answers with a deep groan. You glimpse a silver feather beneath the water.'}
    ]},
    {chapter:'I · THE WHITE SHORE',location:'The Lantern Village',title:'The Warmest Fire',text:'In a fishing village, every hearth is cold. A blue flame burns in the old lighthouse, but the villagers will not approach it. They say the light shows each person the one they most regret losing.\n\nKael stares at the beacon. “I could see her again.”',line:'<b>Kael:</b> “If the star can give her back, would you ask it to?”',choices:[
      {label:'Enter the lighthouse with Kael.',hint:'Share his grief · deepen your bond',effect:{bond:2,flag:'sharedGrief',journal:'You faced the lighthouse visions beside Kael.'},next:2,feedback:'The light shows you a memory too. Kael steps out crying—but smiling, for the first time.'},
      {label:'Rally the villagers to relight every hearth.',hint:'Spend 4 gold · restore their hope',requiresGold:4,effect:{gold:-4,will:2,flag:'litHearths',journal:'You helped relight the village hearths.'},next:2,feedback:'One by one, the fires return. The village answers the star with its own small lights.'},
      {label:'Smother the lighthouse flame.',hint:'Protect Kael from a dangerous illusion',effect:{xp:25,flag:'dousedBeacon',journal:'You extinguished the lighthouse flame.'},next:2,feedback:'The blue fire fades. Kael is angry—but the villagers are safe from its spell.'}
    ]},
    {chapter:'II · THE DEEP WINTER',location:'The Aurora Gate',title:'The Star’s True Name',text:'At the northern edge of the world, the aurora forms a great, translucent door. Beyond it waits a creature made of winter light. It knows Kael’s mother’s name—and the name she gave him as a child.\n\nThe star is not a weapon. It is a traveler, lost between worlds, trying to go home.',line:'<b>Kael:</b> “My mother used to say: a light is not lost if someone remembers it.”',choices:[
      {label:'Speak the name Kael remembers from the song.',hint:'Requires that you listened together',requiresFlag:'heardSong',effect:{will:2,xp:35,flag:'spokeName',journal:'You spoke the star’s true name.'},next:3,feedback:'The aurora parts. The star recognizes its name—and the path home.'},
      {label:'Offer the star your own brightest memory.',hint:'Give something precious to make a bridge',effect:{hp:-1,will:1,flag:'offeredMemory',journal:'You offered the star one of your brightest memories.'},next:3,feedback:'The memory leaves you like a breath on glass. In its place, a bridge of light appears.'},
      {label:'Use the silver feather to open the gate.',hint:'Requires the feather from the ice',requiresItem:'Silver Star-Feather',effect:{will:2,flag:'featherGate',journal:'You opened the aurora gate with the star-feather.'},next:3,feedback:'The feather turns to light in your hand. The gate opens without asking for more.'}
    ]},
    {chapter:'III · THE LAST HORIZON',location:'The Edge of the World',title:'A Light’s Choice',text:'The winter star hovers before the open gate. Kael’s mother’s voice sings from within it. The star can carry her echo home—but if it leaves, the frozen sea will take months to thaw.\n\nKael reaches for your hand. “We can let go, and still keep what she gave us.”',line:'<b>Kael:</b> “Tell me what kind of dawn we should make.”',choices:[
      {label:'Open the gate. Let the star find its way home.',hint:'End the winter; say goodbye to the echo',effect:{flag:'openedGate',xp:60,journal:'You opened the gate and let the winter star go home.'},ending:'home'},
      {label:'Ask the star to stay as a guardian of the sea.',hint:'Keep a little magic here',effect:{flag:'starStayed',xp:60,journal:'You asked the star to remain and guard the sea.'},ending:'guardian'},
      {label:'Give Kael the choice, and stand with him.',hint:'Your bond will shape the ending',effect:{flag:'kaelChooses',xp:60,journal:'You let Kael choose what to do with the star.'},ending:'together'}
    ]}
  ],endings:{home:{title:'The First Thaw',text:'The star sails through the aurora gate. Snow loosens its hold, and the tide returns to the north. Kael hears his mother’s song fade into the sky—and carries it in his own voice.'},guardian:{title:'The Northern Light',text:'The star chooses to stay, shining above the thawing sea. Ships find their way home by its light. Kael becomes its first navigator, and the old songs find a new verse.'},together:{title:'A Song Between Worlds',text:'Kael speaks his mother’s name and lets the star decide. It leaves one bright spark in his palm—a promise, not a ghost. Together, you watch the horizon turn gold.'}}},
  veil:{title:'The Sunken Archive',kind:'A CITY BENEATH THE SANDS',tag:'THE BURIED EMPIRE',icon:'☼',art:'green',length:'4 chapters',summary:'An ancient city rises from the desert every hundred years. This time, it has returned with its doors open—and its people still inside.',companion:'Nima Ashari',companionIcon:'⌁',companionLine:'“My grandmother mapped these ruins from stories. I never thought the city would remember her name.”',nodes:[
    {chapter:'I · THE MOVING DUNES',location:'The Glass Desert',title:'A City on the Horizon',text:'The dunes pull apart like curtains. Gold towers rise where no map says they should be. Nima, an apprentice cartographer, unfolds her grandmother’s last map. Its ink moves, drawing a new road.\n\n“Someone is changing the city from inside,” she says. “Or it is changing itself.”',choices:[
      {label:'Follow the map’s moving ink.',hint:'Trust Nima’s inheritance · strengthen your bond',effect:{bond:2,will:1,flag:'trustedMap',journal:'You trusted Nima’s changing map.'},next:1,feedback:'The map settles when Nima holds it. A new constellation appears, pointing below.'},
      {label:'Climb a tower and survey the ruins.',hint:'Take the high ground · find a rare relic',effect:{xp:20,item:'Sunstone Compass',flag:'surveyedCity',journal:'You surveyed the risen city from above.'},next:1,feedback:'From the tower, the streets form the shape of an eye. You find a sunstone compass in its nest.'},
      {label:'Enter through the nearest open gate.',hint:'Move fast · earn a little gold',effect:{gold:9,flag:'rushedIn',journal:'You entered the city before the dunes could close.'},next:1,feedback:'You slip through as sand pours behind you. A merchant’s hidden coin purse is yours.'}
    ]},
    {chapter:'I · THE MOVING DUNES',location:'The Hall of Names',title:'A Thousand Reflections',text:'The hall is filled with mirrors. Each one reflects a different version of you: crowned, forgotten, dead, beloved. At the far end, a child with Nima’s eyes traces names into the dust.\n\nNima stops breathing. “That’s my grandmother. She should be ninety years old.”',line:'<b>Nima:</b> “If this place can keep her, maybe it can keep anyone.”',choices:[
      {label:'Ask the child what the city wants.',hint:'Listen before acting · earn insight',effect:{will:2,flag:'askedTheCity',journal:'You asked the city what it wanted.'},next:2,feedback:'The child points to a name scratched out of every mirror: the city’s own.'},
      {label:'Break the mirrors before they can trap anyone.',hint:'Protect Nima · risk angering the city',effect:{hp:-1,xp:25,flag:'brokeMirrors',journal:'You broke the mirrors in the Hall of Names.'},next:2,feedback:'The glass falls like rain. The child vanishes, and the city groans beneath your feet.'},
      {label:'Take the child’s hand and follow her.',hint:'Trust the impossible',effect:{bond:1,item:'Memory Thread',flag:'followedChild',journal:'You followed the child deeper into the city.'},next:2,feedback:'Her hand is warm. A golden thread winds around your wrist, leading you onward.'}
    ]},
    {chapter:'II · THE BURIED ARCHIVE',location:'The Unwritten Room',title:'The City’s Last Page',text:'In the archive’s center, a blank book rests on a stone lectern. The city has been trying to write its own name for a thousand years—but the final page is missing. Nima finds it folded inside her grandmother’s map.\n\nThe moment she unfolds it, the sand begins to fall. The city is running out of time.',line:'<b>Nima:</b> “If I write the name, I decide what happens to everyone here. Help me choose.”',choices:[
      {label:'Write the city’s name and restore its people.',hint:'Only the living can choose what comes next',effect:{xp:35,will:-1,flag:'namedCity',journal:'You helped Nima write the city’s forgotten name.'},next:3,feedback:'The letters shine. Behind every mirror, someone opens their eyes.'},
      {label:'Erase the old empire and let the ruins rest.',hint:'Requires the city’s trust',requiresFlag:'askedTheCity',effect:{will:2,flag:'freedCity',journal:'You freed the city from its old name.'},next:3,feedback:'The page turns to clean sand. The city exhales, and the doors unlock.'},
      {label:'Bind the city to Nima’s map.',hint:'Keep the city safe, but carry its burden',effect:{gold:12,flag:'boundCity',journal:'You bound the city to Nima’s map.'},next:3,feedback:'The map draws itself around the towers. Nima takes it with both hands.'}
    ]},
    {chapter:'III · THE CITY REMEMBERS',location:'The Open Gate',title:'What We Leave Behind',text:'The city stands in the sunrise, no longer hidden. Its people gather at the gate. Some want to go; some want to remain; some only want to know what year it is. Nima’s grandmother waits among them, young and bewildered.\n\nThe dunes are already shifting. Your answer will become the city’s next story.',line:'<b>Nima:</b> “A map is a promise that someone can find their way back.”',choices:[
      {label:'Guide the people out into the living world.',hint:'Choose a future beyond the walls',effect:{flag:'ledPeopleOut',xp:60,journal:'You led the city’s people into the living world.'},ending:'dawn'},
      {label:'Help them rebuild the city as a sanctuary.',hint:'Make a home for the lost',effect:{flag:'madeSanctuary',xp:60,journal:'You made the city a sanctuary for the lost.'},ending:'sanctuary'},
      {label:'Give Nima the map. Let her decide what to preserve.',hint:'Your bond will shape the ending',effect:{flag:'trustedNima',xp:60,journal:'You entrusted the city’s fate to Nima.'},ending:'map'}
    ]}
  ],endings:{dawn:{title:'The Open Road',text:'The people cross the threshold into the morning. Nima’s grandmother sees the desert and laughs at the sheer size of the world. The city fades behind you, but its people are no longer lost.'},sanctuary:{title:'A Place for the Unwritten',text:'The city opens its gates to every traveler the desert has swallowed. Nima draws new roads on the map, while her grandmother tells stories no archive could hold.'},map:{title:'The Cartographer’s Promise',text:'Nima keeps the map, but leaves the final page blank. The city becomes a promise that can change with every hand that holds it—and she invites you to help draw the next line.'}}}
