let state=null, selectedCampaign='ash', selectedHero='sentinel', toastTimer;
const itemDetails={
  'Cinderglass Shard':{icon:'◇',desc:'A warm fragment of the first queen’s spell.',bonus:'Equipped: +1 will'},
  'Pilgrim’s Key':{icon:'⚿',desc:'A bronze key from the road beneath the mountain.',bonus:'Equipped: +1 gold on choices'},
  'Silver Star-Feather':{icon:'❄',desc:'A feather of light, cold as the northern sea.',bonus:'Equipped: +1 will'},
  'Sunstone Compass':{icon:'◈',desc:'Points toward what the holder has forgotten.',bonus:'Equipped: +1 will'},
  'Memory Thread':{icon:'⌁',desc:'A golden thread leading through the city’s memories.',bonus:'Equipped: +1 vitality'}
};
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function startGame(){
  const h=heroes[selectedHero];
  state={campaign:selectedCampaign,hero:selectedHero,node:0,hp:h.stats.hp,maxHp:h.stats.hp,will:h.stats.will,maxWill:h.stats.will,gold:h.stats.gold,xp:0,level:1,bond:0,flags:{},items:[],equipped:null,upgrades:[],journal:[],done:false,ending:null,feedback:null};
  save();renderGame();window.scrollTo({top:0,behavior:'smooth'});
}
function save(){try{localStorage.setItem('mythos-memory-save',JSON.stringify(state));}catch(e){}}
function loadSave(){try{const s=JSON.parse(localStorage.getItem('mythos-memory-save'));if(!s||!campaigns[s.campaign]||!heroes[s.hero])return false;state=s;return true;}catch(e){return false;}}
function resumeGame(){if(loadSave())renderGame();else toast('No saved adventure found yet.');}
function hasSave(){try{return !!localStorage.getItem('mythos-memory-save');}catch(e){return false;}}
function returnToTitle(){state=null;renderTitle();window.scrollTo({top:0,behavior:'smooth'});return false;}
function renderTitle(){
 const c=campaigns[selectedCampaign];
 document.getElementById('app').innerHTML=`<section class="screen title-screen"><div class="title-heading"><div class="eyebrow">A TALE SHAPED BY YOU</div><h1>Legends are <em>chosen.</em></h1><p>Three forgotten histories. Three unlikely heroes. Every promise, sacrifice, and decision changes the world you leave behind.</p></div><div class="creation-layout"><section class="section-card"><div class="section-title"><h2>Choose your history</h2><span>01 — 03</span></div><div class="campaign-list">${Object.entries(campaigns).map(([id,x])=>`<button class="campaign-card ${selectedCampaign===id?'selected':''}" onclick="selectCampaign('${id}')"><span class="campaign-art">${x.icon}</span><span class="campaign-meta"><span class="tag">${x.tag}</span><h3>${x.title}</h3><p>${x.summary}</p><span class="campaign-foot"><span>✦ ${x.length}</span><span>◷ ~15 MIN</span></span></span><span class="arrow">›</span></button>`).join('')}</div></section><section class="section-card"><div class="section-title"><h2>Choose your hero</h2><span>01 — 03</span></div><div class="hero-options">${Object.entries(heroes).map(([id,h])=>`<button class="hero-card ${selectedHero===id?'selected':''}" onclick="selectHero('${id}')"><span class="hero-sigil">${h.sigil}</span><span class="hero-info"><strong>${h.name}</strong><small>${h.role}</small><span class="specialty">${h.specialty}</span></span><span class="check">✦</span></button>`).join('')}</div><div class="creation-note"><span>✦</span><span><b>${heroes[selectedHero].perk}</b><br>Choices are never locked to a class. Your strengths shape the journey, not the limits of it.</span></div></section></div><div class="start-row"><button class="primary-button" onclick="startGame()">BEGIN YOUR LEGEND <span>→</span></button></div>${hasSave()?'<button class="resume-link" onclick="resumeGame()">↻ &nbsp; CONTINUE YOUR SAVED TALE</button>':''}</section>`;
}
function selectCampaign(id){selectedCampaign=id;renderTitle();}
function selectHero(id){selectedHero=id;renderTitle();}
function applyEffects(e){
 if(!e)return;
 ['hp','will','gold'].forEach(k=>{if(e[k])state[k]=k==='hp'?Math.max(1,Math.min(state.maxHp,state.hp+e[k])):k==='will'?Math.max(0,Math.min(state.maxWill,state.will+e[k])):Math.max(0,state.gold+e[k]);});
 if(e.xp){state.xp+=e.xp;while(state.xp>=100){state.xp-=100;state.level++;state.maxHp++;state.maxWill++;state.hp=Math.min(state.maxHp,state.hp+1);state.will=Math.min(state.maxWill,state.will+1);toast(`Level up! You reached level ${state.level}.`);}}
 if(e.bond)state.bond=Math.max(0,state.bond+e.bond);
 if(e.item&&!state.items.includes(e.item)){state.items.push(e.item);toast(`Found: ${e.item}`);}
 if(e.flag)state.flags[e.flag]=true;
 if(e.journal)state.journal.unshift(e.journal);
}
function choose(index){
 const camp=campaigns[state.campaign],node=camp.nodes[state.node],choice=node.choices[index];if(!choice)return;
 if(choice.requiresGold&&state.gold<choice.requiresGold){toast(`You need ${choice.requiresGold} gold for this choice.`);return;}
 if(choice.requiresFlag&&!state.flags[choice.requiresFlag]){toast('A choice from an earlier chapter will open this path.');return;}
 if(choice.requiresItem&&!state.items.includes(choice.requiresItem)){toast(`You need ${choice.requiresItem} to take this path.`);return;}
 applyEffects(choice.effect);state.feedback=choice.feedback||'';
 if(choice.ending){state.done=true;state.ending=choice.ending;}else{state.node=choice.next;}
 save();renderGame();window.scrollTo({top:0,behavior:'smooth'});
}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500);}
function toggleSound(){const el=document.getElementById('sound-icon');el.textContent=el.textContent==='♫'?'♪':'♫';toast('The tale is best enjoyed with your own soundtrack.');}
function showHelp(){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" onclick="closeModal(event)"><div class="modal" onclick="event.stopPropagation()"><button class="close-button" onclick="closeModal()">×</button><div class="eyebrow">A FIELD GUIDE</div><h2>How to play</h2><p>Choose your history and hero, then read closely: the words you choose shape who trusts you, what you discover, and how each tale ends.</p><ul><li><b>Vitality</b> tracks your health. Dangerous choices may cost a point, but it never falls below one.</li><li><b>Will</b> is your resolve and magic. Spend gold to buy permanent upgrades for this adventure.</li><li><b>Items</b> are found through decisions. Equip one to reveal its small passive bonus.</li><li>Your progress is saved in this browser automatically. Replay a different history to discover its other endings.</li></ul><div class="modal-actions"><button class="primary-button" onclick="closeModal()">UNDERSTOOD</button></div></div></div>`;}
function closeModal(e){if(!e||e.target.classList.contains('modal-backdrop'))document.getElementById('modal-root').innerHTML='';}

